import { create_list_edit_delete_splay_categories } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import { uploadToS3 } from "@/mixins/uploadToS3.js";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogCreateCategory: Boolean
  },
  mixins: [uploadToS3],
  components: {
    SnackBar
  },
  data: () => ({
    category: "",
    interval: "10",
    loading: false,
    imageUrl: null,
    selectedFile: null,
    SnackBarComponent: {},
    intervalItems: [{
      title: "10",
      value: "10"
    }, {
      title: "15",
      value: "15"
    }, {
      title: "30",
      value: "30"
    }, {
      title: "45",
      value: "45"
    }, {
      title: "60",
      value: "60"
    }]
  }),
  watch: {
    DialogCreateCategory(val) {
      if (!val) {
        this.category = "";
        this.interval = "10";
        this.imageUrl = null;
        this.selectedFile = null;
      }
    }
  },
  methods: {
    async CreateCategory() {
      this.loading = true;
      try {
        let uploadedImageUrl = null;
        if (this.selectedFile) {
          const key = `categories/${Date.now()}-${this.selectedFile.name}`;
          uploadedImageUrl = await uploadToS3(this.selectedFile, key);
        }
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_splay_categories, {
          input: {
            action_type: "CREATE",
            question_interval: this.interval,
            splay_category_name: this.category,
            repository_source: "CUSTOM",
            splay_category_image: uploadedImageUrl
          }
        }));
        const resultObj = JSON.parse(result.data.create_list_edit_delete_splay_categories);
        if (resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: resultObj.Message
          };
        }
        this.DialogCreateCategoryEmit(2);
      } catch (error) {
        console.error(error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Failed to create category, try again"
        };
      } finally {
        this.loading = false;
      }
    },
    DialogCreateCategoryEmit(Toggle) {
      this.$emit("clicked", Toggle);
    },
    openFilePicker() {
      this.$refs.fileInput.$el.querySelector("input").click();
    },
    OnFileSelect(file) {
      this.selectedFile = file || null;
      this.imageUrl = null;
      if (file) {
        const reader = new FileReader();
        reader.onload = e => {
          this.imageUrl = e.target.result;
        };
        reader.readAsDataURL(file);
      }
    }
  }
};
